en:
//【首領】
<voice name='首領' class='首領姉' src='voice/ma05/0160640b31'>
//「……」
"......"

//【首領弟】
<voice name='首領弟' class='首領弟' src='voice/ma05/0160650b32'>
//「違う？」
"Right?"

pt:
//【首領弟】
<voice name='首領弟' class='首領弟' src='voice/ma05/0160650b32'>
