pt:
//【首領弟】
<voice name='首領弟' class='首領弟' src='voice/ma05/0160830b32'>
//「聞くわけないじゃん。
//　何言ってんのさ、姉さん」
"Do que você está falando? Claro que não obedecem."

en:
//【首領】
<voice name='首領' class='首領姉' src='voice/ma05/0160840b31'>
